// ══════════════════════════════════════════════════════════
// INPUT ROUTER v2.0
// Parses ALL event types: message, callback, payment, checkout
// NEW: detects chat.type for private/group access split
// ══════════════════════════════════════════════════════════
const item = $input.first().json;

// ── Pre-checkout (Stars payment confirmation) ───────────────
if (item.pre_checkout_query) {
  return [{ json: {
    type: 'pre_checkout',
    preCheckoutId: item.pre_checkout_query.id,
    chatId: item.pre_checkout_query.from.id,
    username: item.pre_checkout_query.from.username || 'user',
    firstName: item.pre_checkout_query.from.first_name || ''
  }}];
}

// ── Successful Stars payment ────────────────────────────────
if (item.message && item.message.successful_payment) {
  return [{ json: {
    type: 'payment_success',
    chatId: item.message.chat.id,
    username: item.message.from.username || 'buyer',
    firstName: item.message.from.first_name || '',
    chatType: item.message.chat.type
  }}];
}

// ── Callback query (inline buttons) ─────────────────────────
if (item.callback_query) {
  const data = item.callback_query.data || '';
  const chatType = item.callback_query.message.chat.type;
  return [{ json: {
    type: data.startsWith('ch_') ? 'chart' : 'button',
    chatId: item.callback_query.message.chat.id,
    username: item.callback_query.from.username || 'user',
    firstName: item.callback_query.from.first_name || '',
    callbackData: data,
    callbackQueryId: item.callback_query.id,
    chatType
  }}];
}

// ── Regular message ──────────────────────────────────────────
if (item.message && item.message.text) {
  const text = item.message.text;
  const chatType = item.message.chat.type; // private | group | supergroup
  const chatId   = item.message.chat.id;
  const username = item.message.from.username   || 'user';
  const firstName = item.message.from.first_name || '';

  let type = null;
  if (text.startsWith('/start'))       type = 'start';
  else if (text.startsWith('/scan'))   type = 'button';
  else if (text.startsWith('/help') || text.startsWith('/info')) type = 'info';
  else return [];

  // Group/supergroup hit start or scan → paywall check path
  if ((chatType === 'group' || chatType === 'supergroup') && (type === 'start' || type === 'button')) {
    type = 'group_check';
  }

  return [{ json: { type, chatId, username, firstName, chatType, callbackData: null, callbackQueryId: null } }];
}

return [];

// ══════════════════════════════════════════════════════════
// ACCESS GATE v2.0
// - Private chat: ALWAYS allowed (free)
// - Group/supergroup: check CRM for active subscription
// - Manual delete from sheet = instant revocation
// ══════════════════════════════════════════════════════════
const router = $('Input Router').first().json;
const targetChatId = router.chatId.toString();
const chatType = router.chatType || 'private';

// Private chats are always free — no CRM check needed
if (chatType === 'private') {
  return [{ json: { access: 'granted', chatId: router.chatId, username: router.username, firstName: router.firstName, chatType } }];
}

// For groups: check CRM
let rows = [];
try {
  rows = $input.all().map(i => i.json).filter(r => r && r.chat_id);
} catch(e) { rows = []; }

const found = rows.find(r => r.chat_id && r.chat_id.toString() === targetChatId);

if (!found) {
  return [{ json: { access: 'denied_not_found', chatId: router.chatId, username: router.username, firstName: router.firstName, chatType } }];
}

const today = new Date().toISOString().split('T')[0];
const validStatuses = ['premium', 'admin_premium'];

if (validStatuses.includes(found.status)) {
  if (found.expiry_date && found.expiry_date < today) {
    return [{ json: { access: 'denied_expired', chatId: router.chatId, username: router.username, firstName: router.firstName, chatType } }];
  }
  return [{ json: { access: 'granted', chatId: router.chatId, username: router.username, firstName: router.firstName, chatType } }];
}

return [{ json: { access: 'denied_unpaid', chatId: router.chatId, username: router.username, firstName: router.firstName, chatType } }];

// ══════════════════════════════════════════════════════════
