// ══════════════════════════════════════════════════════════
// SMART PARSER v2.0
// NEW: Extended promo condition detector (8 patterns)
// NEW: Cleaner message format with promo badges
// ══════════════════════════════════════════════════════════
const html = $input.first().json.data || '';

// Trim footer garbage
const cleanHtml = html.includes('<section class="spolupracujeme">')
  ? html.split('<section class="spolupracujeme">')[0]
  : html;

const items = cleanHtml.split(/itemtype="https?:\/\/schema.org\/Product"/);
items.shift();

const TARGET_STORES = ['Tesco', 'Kaufland', 'Lidl', 'Billa'];
const TARGET_BRANDS = ['monster', 'red bull', 'hell', 'tiger', 'semtex', 'big shock'];

// ── Promo condition detector (8 patterns) ──────────────────
function detectPromo(block) {
  const b = block.toLowerCase();
  // Pattern 1: App required
  if (/s aplikáciou|s appkou|v aplikácii/.test(b))      return '📱 <i>S aplikáciou</i>';
  // Pattern 2: Loyalty card
  if (/clubcard|vernostná karta|s kartou|karta zákazníka/.test(b)) return '💳 <i>S vernostnou kartou</i>';
  // Pattern 3: Buy N get price (2ks, 3ks, od 2)
  const nksMatch = b.match(/od\s*(\d+)\s*ks|pri kúpe\s*(\d+)|kúpte\s*(\d+)|(\d+)\s*ks/);
  if (nksMatch) {
    const n = nksMatch[1] || nksMatch[2] || nksMatch[3] || nksMatch[4];
    return `⚠️ <i>Od ${n} ks</i>`;
  }
  // Pattern 4: Mix & match
  if (/mix|rôzne príchute|viac druhov/.test(b))         return '🔀 <i>Mix variantov</i>';
  // Pattern 5: Member only
  if (/len pre členov|iba pre/.test(b))                  return '👤 <i>Len pre členov</i>';
  // Pattern 6: Limited time
  if (/časovo obmedzené|len dnes|iba dnes/.test(b))      return '⏰ <i>Časovo obmedzené</i>';
  // Pattern 7: Online only
  if (/online|e-shop/.test(b))                           return '🌐 <i>Online only</i>';
  // Pattern 8: Quantity limit
  if (/max\.?\s*\d+|maximálne\s*\d+/.test(b))          return '🔢 <i>Obmedzené množstvo</i>';
  return '';
}

const storeDeals = { Tesco: [], Kaufland: [], Lidl: [], Billa: [] };
const deals = [];
let hasAnyDiscount = false;

for (const item of items) {
  const nameMatch = item.match(/itemprop="name"\s+content="(.*?)"/);
  if (!nameMatch) continue;

  let fullName = nameMatch[1].replace(/500\s*ml|energetický nápoj/gi, '').trim();
  const foundBrand = TARGET_BRANDS.find(b => fullName.toLowerCase().includes(b));
  if (!foundBrand) continue;

  if (item.toLowerCase().includes('viac druhov')) fullName += ' (rôzne príchute)';

  // Price extraction
  const priceMatch =
    item.match(/class="[^"]*color-red[^"]*">\s*([\d,]+)/i) ||
    item.match(/([\d,]+)\s*<span class="currency">/i);
  if (!priceMatch) continue;
  const price = parseFloat(priceMatch[1].replace(',', '.'));
  if (isNaN(price) || price <= 0) continue;

  // Discount badge
  const discountMatch = item.match(/-(\d+)\s*(?:<span[^>]*>)?%/i);
  const discountBadge = discountMatch ? ` 🔻<b>-${discountMatch[1]}%</b>` : '';

  // Promo condition (NEW: extended detector)
  const promoCondition = detectPromo(item);
  const conditionLine = promoCondition ? `\n    ↳ ${promoCondition}` : '';

  // Store matching
  const storesBlockMatch = item.match(/<ul class="product-action-stores[\s\S]*?<\/ul>/i);
  const storesBlock = storesBlockMatch ? storesBlockMatch[0].toLowerCase() : '';

  for (const store of TARGET_STORES) {
    if (
      storesBlock.includes(`="${store.toLowerCase()}"`) ||
      storesBlock.includes(`/${store.toLowerCase()}`)
    ) {
      const icon = foundBrand === 'monster' ? '🥤' : foundBrand === 'red bull' ? '🔋' : '⚡';
      const dealLine = `${icon} <b>${fullName}</b>\n    💰 <b>${price.toFixed(2)}€</b>${discountBadge}${conditionLine}`;

      storeDeals[store].push(dealLine);
      hasAnyDiscount = true;
      deals.push({ store, brand: foundBrand, itemName: fullName, price });
    }
  }
}

// ── Build message ───────────────────────────────────────────
const storeEmoji = { Tesco: '🟥', Kaufland: '🟨', Lidl: '🟦', Billa: '🟩' };
let messageText = '⚡️ <b>Радар энергетиков — Monster Hunter SK</b>\n';
messageText += `<i>Обновлено: ${new Date().toLocaleString('ru-RU', { timeZone: 'Europe/Bratislava', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' })}</i>\n\n`;

for (const store of TARGET_STORES) {
  const unique = [...new Set(storeDeals[store])];
  if (unique.length > 0) {
    messageText += `${storeEmoji[store]} <b>${store}</b>\n`;
    unique.forEach(d => { messageText += `${d}\n\n`; });
  }
}

if (!hasAnyDiscount) {
  messageText = '😔 <b>Сейчас подтверждённых скидок не найдено.</b>\n\n<i>Мониторинг продолжается — я сообщу, как только появятся акции!</i>';
}

return [{ json: { parsedText: messageText.trim(), deals } }];

// ══════════════════════════════════════════════════════════
// HISTORY MANAGER v2.0
// Replaces 3 old nodes: Read + Append + Write (+ Deduplicate)
// ══════════════════════════════════════════════════════════
const staticData = $getWorkflowStaticData('global');
let history = staticData.priceHistory || [];
const lastHash = staticData.lastMessageHash || '';

const parseData = $('Smart Parser').first().json;
const newDeals = parseData.deals || [];
const parsedText = parseData.parsedText || '';
const timestamp = new Date().toISOString();

// Append new price points
for (const d of newDeals) {
  history.push({ timestamp, store: d.store, brand: d.brand, itemName: d.itemName, price: d.price });
}

// Cap at 2000 entries
if (history.length > 2000) history = history.slice(-2000);

// Write back
staticData.priceHistory = history;

// ── Deduplication check ─────────────────────────────────────
const isManualTrigger = (() => {
  try { return !!$('Input Router').first().json.chatId; } catch(e) { return false; }
})();

if (!isManualTrigger) {
  if (lastHash === parsedText.trim() && parsedText.trim() !== '') {
    // No change since last scheduled run — suppress broadcast
    return [];
  }
  staticData.lastMessageHash = parsedText.trim();
}

// ── Price Alert: detect historical minimums ─────────────────
const priceAlerts = [];
for (const d of newDeals) {
  const storeHistory = history.filter(h => h.store === d.store && h.brand === d.brand);
  if (storeHistory.length < 3) continue; // Need at least 3 data points
  const allPrices = storeHistory.map(h => h.price);
  const historicMin = Math.min(...allPrices);
  // Alert if current price <= historic min + 5% margin
  if (d.price <= historicMin * 1.05 && d.price === Math.min(...allPrices)) {
    const brandLabel = d.brand.split(' ').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
    const storeEmoji = { Tesco: '🟥', Kaufland: '🟨', Lidl: '🟦', Billa: '🟩' }[d.store] || '🏪';
    priceAlerts.push(`🔔 <b>ИСТОРИЧЕСКИЙ МИН!</b>\n${storeEmoji} <b>${brandLabel}</b> в <b>${d.store}</b>\n💰 <b>${d.price.toFixed(2)}€</b> — лучшая цена за всё время наблюдений!`);
  }
}

return [{ json: { parsedText, deals: newDeals, priceAlerts } }];

// ══════════════════════════════════════════════════════════
// BUILD REPLY MARKUP v2.0
// Single source of truth for inline buttons
// Used by both Send Result (manual) and Broadcast
// ══════════════════════════════════════════════════════════
const deals = $('History Manager').first().json.deals || [];
const parsedText = $('History Manager').first().json.parsedText || '';

const storeMap   = { Tesco: 't', Kaufland: 'k', Lidl: 'l', Billa: 'b' };
const storeEmoji = { Tesco: '🟥', Kaufland: '🟨', Lidl: '🟦', Billa: '🟩' };

const seen = new Set();
const rows = [[{ text: '🔄 Обновить', callback_data: 'scan_now' }]];

for (const d of deals) {
  if (!seen.has(d.store)) {
    seen.add(d.store);
    const init  = storeMap[d.store] || d.store.charAt(0).toLowerCase();
    const emoji = storeEmoji[d.store] || '🏪';
    rows.push([{ text: `${emoji} ${d.store} — График цен`, callback_data: `ch_${init}` }]);
  }
}

const replyMarkup = { inline_keyboard: rows };

return [{ json: { parsedText, deals, replyMarkup } }];

