// ══════════════════════════════════════════════════════════
// FRIDAY DIGEST BUILDER v2.0
// Triggered every Friday 17:00
// Builds top-3 best deals of the week summary
// ══════════════════════════════════════════════════════════
const staticData = $getWorkflowStaticData('global');
const history = staticData.priceHistory || [];

if (history.length === 0) {
  return [{ json: { digestText: '📅 <b>Пятничный дайджест</b>\n\n<i>Данных за эту неделю пока нет. Радар только начал мониторинг!</i>' } }];
}

// Get entries from last 7 days
const weekAgo = new Date();
weekAgo.setDate(weekAgo.getDate() - 7);
const weekHistory = history.filter(h => new Date(h.timestamp) >= weekAgo);

// Find best price per brand+store combo
const bestDeals = {};
for (const e of weekHistory) {
  const key = `${e.brand}|${e.store}`;
  if (!bestDeals[key] || e.price < bestDeals[key].price) {
    bestDeals[key] = e;
  }
}

// Sort by price ascending, take top 5
const topDeals = Object.values(bestDeals)
  .sort((a, b) => a.price - b.price)
  .slice(0, 5);

const storeEmoji = { Tesco: '🟥', Kaufland: '🟨', Lidl: '🟦', Billa: '🟩' };

let digestText = '📅 <b>Пятничный дайджест — Топ скидок недели</b>\n';
digestText += `<i>${new Date().toLocaleDateString('ru-RU', { day: '2-digit', month: 'long' })}</i>\n\n`;

if (topDeals.length === 0) {
  digestText += '<i>На этой неделе особых акций не было.</i>';
} else {
  topDeals.forEach((d, i) => {
    const medal = ['🥇', '🥈', '🥉', '4️⃣', '5️⃣'][i];
    const brandLabel = d.brand.split(' ').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
    const emoji = storeEmoji[d.store] || '🏪';
    digestText += `${medal} <b>${brandLabel}</b> — ${emoji} ${d.store}\n`;
    digestText += `   💰 <b>${d.price.toFixed(2)}€</b>\n\n`;
  });
}

digestText += '\n📊 Нажми на кнопку магазина, чтобы увидеть полный график цен:';

const rows = [[{ text: '🔄 Проверить сейчас', callback_data: 'scan_now' }]];
const seenStores = new Set(topDeals.map(d => d.store));
const storeMap = { Tesco: 't', Kaufland: 'k', Lidl: 'l', Billa: 'b' };

for (const store of seenStores) {
  const emoji = storeEmoji[store] || '🏪';
  const init  = storeMap[store] || store.charAt(0).toLowerCase();
  rows.push([{ text: `${emoji} ${store} — График`, callback_data: `ch_${init}` }]);
}

return [{ json: { digestText, replyMarkup: { inline_keyboard: rows } } }];

